            if (thing->HasBaseDef())
                PRenderManager->Draw3DScaledText(C3DVector(VIRTUAL_SCREEN_WIDTH * 0.45f, GFAYToVY(45.0f) + GFAYToVY(16.0f) * i, 0.0f), 0.7f,
