                    (GetThingManager().IsNonScriptedEntitesPauseMode() || GetThingManager().IsAllEntitesPauseMode()))
                    continue;
                if (NCreatureMode::IsRolling(*thing) && !PShotDef->CanHitRollingTargets)
                    continue;
